list.query:
from(bucket: "streaming_quantum")
  |> range(start: -15m)
  |> filter(fn: (r) => r._measurement == "drift_events" and r._field == "drift_detected" and r._value == 1)

targets.query:
from(bucket: "streaming_quantum")
  |> range(start: -15m)
  |> filter(fn: (r) => r._measurement == "prequential_accuracy" and r._field == "rolling_accuracy")
